    if not threes:
        return g
    rs = sorted({r for r, c in threes}); cs = sorted({c for r, c in threes})
    horizontal = len(rs) < len(cs)

    def runs(vals):
        starts, prev = [], -10
        for v in sorted(vals):
            if v - prev > 1:
                starts.append(v)
            prev = v
        return starts

    # detect geometry BEFORE erasing (lines may be fully erased)
    marked_rows = [r for r in range(n) if any(g[r][c] in (2, 3) for c in range(n))]
    marked_cols = [c for c in range(n) if any(g[r][c] in (2, 3) for r in range(n))]
    rstarts = runs(marked_rows)
    cstarts = runs(marked_cols)
    w = (rs[-1] - rs[0] + 1) if horizontal else (cs[-1] - cs[0] + 1)
    p = rstarts[1] - rstarts[0] if len(rstarts) > 1 else cstarts[1] - cstarts[0]
    # rebuild uniform line starts (erased lines may be missing from runs)
    def full_lines(starts):
        s0 = starts[0]
        return [s0 + i * p for i in range((n - w) // p + 1)]
    rstarts_f = full_lines(rstarts)
    cstarts_f = full_lines(cstarts)

    # erase region
    for r, c in threes:
        g[r][c] = 0

    def box_cells(r0, c0):
        return [(r - r0, c - c0) for r in range(r0, r0 + w) for c in range(c0, c0 + w) if g[r][c] == 2]

    # box pattern from a box outside the erased line
    pat = None
    if horizontal:
        line_idx = rstarts_f.index(rs[0])
        cands = [(i, j) for i in range(len(rstarts_f)) for j in range(len(cstarts_f)) if i != line_idx]
        for i, j in cands:
            cells = box_cells(rstarts_f[i], cstarts_f[j])
            if len(cells) >= 3:
                pat = sorted(cells); break
    else:
        line_idx = cstarts_f.index(cs[0])
        cands = [(i, j) for i in range(len(rstarts_f)) for j in range(len(cstarts_f)) if j != line_idx]
        for i, j in cands:
            cells = box_cells(rstarts_f[i], cstarts_f[j])
            if len(cells) >= 3:
                pat = sorted(cells); break

    size = len(rstarts_f)
    # fractal rule: meta grid (which band/box lines hold shapes) must equal box pattern
    target = [[0] * size for _ in range(size)]
    for (r, c) in pat:
        if r < size and c < size:
