            r0, c0 = rstarts_f[line_idx], cstarts_f[k]
        else:
            if any(g[r][c] == 2 for r in range(rstarts_f[k], rstarts_f[k] + w)
                   for c in range(cstarts_f[line_idx], cstarts_f[line_idx] + w)):
